# frozen_string_literal: true

module RuboCop
  module Cop
    module Layout
      # Checks if empty lines exist around the bodies of methods.
      #
      # @example
      #
      #   # good
      #
      #   def foo
      #     # ...
      #   end
      #
      #   # bad
      #
      #   def bar
      #
      #     # ...
      #
      #   end
      class EmptyLinesAroundMethodBody < Base
        include EmptyLinesAroundBody
        include RangeHelp
        extend AutoCorrector

        KIND = 'method'

        def on_def(node)
          check(node, node.body)
        end
        alias on_defs on_def

        def self.perform_body_boundary_inspection(cop, node, body, adjusted_first_line)
          coordinator = cop.is_a?(self) ? cop : new(cop.config, cop.instance_variable_get(:@options))
          coordinator.send(:bind_layout_host, cop)
          coordinator.send(:inspect_enclosing_body, node, body, adjusted_first_line)
        end

        def self.perform_argument_spacing_inspection(cop, node)
          coordinator = cop.is_a?(self) ? cop : new(cop.config, cop.instance_variable_get(:@options))
          coordinator.send(:bind_layout_host, cop)
          coordinator.send(:inspect_invocation_arguments, node)
        end

        def self.perform_exception_keyword_inspection(cop, body, line_of_def_or_kwbegin)
          coordinator = cop.is_a?(self) ? cop : new(cop.config, cop.instance_variable_get(:@options))
          coordinator.send(:bind_layout_host, cop)
          coordinator.send(:inspect_exception_keywords, body, line_of_def_or_kwbegin)
        end

        def self.apply_empty_line_correction(corrector, node)
          offense_style, range = node
          case offense_style
          when :no_empty_lines
            corrector.remove(range)
          when :empty_lines
            corrector.insert_before(range, "\n")
          end
        end
        private

        def style
          :no_empty_lines
        end

        def bind_layout_host(cop)
          @layout_host = cop
          cop
        end

        def host_processed_source
          @layout_host.processed_source
        end

        def host_style_value
          @layout_host.send(:style)
        end

        def host_kind_label
          klass = @layout_host.class
          if klass.const_defined?(:KIND)
            klass::KIND
          else
            KIND
          end
        end

        def host_lines
          source = @layout_host.processed_source
          if source
            source.lines
          else
            []
          end
        end

        def host_buffer
          source = @layout_host.processed_source
          if source
            source.buffer
          else
            nil
          end
        end

        def host_source_line(index)
          source = @layout_host.processed_source
          lines = source.lines
          if index && index >= 0 && index < lines.length
            lines[index]
          else
            lines[index]
          end
        end

        def investigation_host
          @layout_host
        end

        def inspect_enclosing_body(node, body, adjusted_first_line)
          @body_layout_node = node
          @body_layout_body = body
          classify_layout_node(node)
          classify_layout_node(body)
          collect_body_layout_facts(node, body, adjusted_first_line)
          apply_body_empty_line_policy(node, body, adjusted_first_line)
        end

        def collect_body_layout_facts(node, body, adjusted_first_line)
          @body_layout_node = node
          @body_layout_body = body
          capture_body_line_span(node, adjusted_first_line)
          capture_body_style_policy(node)
          capture_body_namespace_shape(body)
          capture_body_child_profile(body)
          capture_body_source_window(node)
          capture_body_comment_guard(node)
          capture_body_visibility_markers(body)
          capture_body_rescue_presence(body)
          capture_body_ensure_presence(body)
          capture_body_begin_shape(body)
          capture_body_send_shape(node)
          capture_body_constant_path(node)
          @body_layout_skip = skip_empty_body_for_style?(body)
          @body_layout_single_line = node.single_line?
          @body_layout_style = host_style_value
          if adjusted_first_line
            @body_layout_first = adjusted_first_line
          else
            @body_layout_first = node.source_range.first_line
          end
          @body_layout_last = node.source_range.last_line
        end

        def apply_body_empty_line_policy(node, body, adjusted_first_line)
          @body_layout_node = node
          return if @body_layout_skip
          return if @body_layout_single_line
          first_line = @body_layout_first
          last_line = @body_layout_last
          current_style = @body_layout_style
          case current_style
          when :empty_lines_except_namespace
            inspect_empty_lines_except_namespace(body, first_line, last_line)
          when :empty_lines_special
            inspect_empty_lines_special(body, first_line, last_line)
          else
            inspect_both_boundaries(current_style, first_line, last_line)
          end
        end

        def inspect_both_boundaries(current_style, first_line, last_line)
          @body_layout_style = current_style
          @body_layout_first = first_line
          @body_layout_last = last_line
          case current_style
          when :beginning_only
            inspect_beginning_boundary(:empty_lines, first_line)
            inspect_ending_boundary(:no_empty_lines, last_line)
          when :ending_only
            inspect_beginning_boundary(:no_empty_lines, first_line)
            inspect_ending_boundary(:empty_lines, last_line)
          else
            inspect_beginning_boundary(current_style, first_line)
            inspect_ending_boundary(current_style, last_line)
          end
        end

        def inspect_source_boundary(current_style, line_no, desc)
          @body_layout_style = current_style
          @body_layout_desc = desc
          msg = body_boundary_message(current_style, desc)
          case current_style
          when :no_empty_lines
            inspect_boundary_line(current_style, line_no, msg, :empty)
          when :empty_lines
            inspect_boundary_line(current_style, line_no, msg, :present)
          end
        end

        def inspect_boundary_line(current_style, line, msg, expectation)
          @body_layout_style = current_style
          @body_layout_line = line
          text = host_source_line(line)
          matched = expectation == :empty ? empty_source_line?(text) : !empty_source_line?(text)
          return unless matched
          register_body_boundary_offense(current_style, line, msg)
        end

        def register_body_boundary_offense(current_style, line, msg)
          @body_layout_style = current_style
          @body_layout_line = line
          offset = current_style == :empty_lines && msg.include?('end.') ? 2 : 1
          buffer = host_buffer
          prepare_layout_range_context(buffer, line + offset)
          range = layout_line_start_range(buffer, line + offset)
          investigation_host.add_offense(range, message: msg) do |corrector|
            self.class.apply_empty_line_correction(corrector, [current_style, range])
          end
        end

        def capture_body_line_span(node, adjusted_first_line)
          @body_layout_node = node
          return :missing unless node
          if adjusted_first_line
            @body_layout_first = adjusted_first_line
          else
            @body_layout_first = node.source_range.first_line
          end
          @body_layout_last = node.source_range.last_line
          range = node.source_range
          @body_layout_begin_pos = range.begin_pos
          @body_layout_end_pos = range.end_pos
          @body_layout_column = range.column
          @body_layout_last_column = range.last_column
          @body_layout_length = @body_layout_end_pos - @body_layout_begin_pos
          @body_layout_label = node.type.to_s
          @body_layout_child_count = node.children.size
          @body_layout_multiline = node.multiline?
          @body_layout_single = node.single_line?
          @body_layout_first_line = node.first_line
          @body_layout_last_line = node.last_line
          @body_layout_span = @body_layout_last_line - @body_layout_first_line
          @body_layout_mid = (@body_layout_first_line + @body_layout_last_line) / 2
          loc = node.loc
          @body_layout_loc_line = loc.line
          @body_layout_loc_column = loc.column
          @body_layout_source_size = node.source.length
          @body_layout_hash = node.hash
          children = node.children
          @body_layout_first_child = children.first
          @body_layout_last_child = children.last
          linespan_tokens = []
          linespan_tokens << @body_layout_label
          linespan_tokens << @body_layout_first_line.to_s
          linespan_tokens << @body_layout_last_line.to_s
          linespan_tokens << @body_layout_length.to_s
          linespan_tokens << @body_layout_child_count.to_s
          @body_layout_digest = linespan_tokens.join(':')
          @body_layout_complete = true
          window = []
          (@body_layout_first_line..@body_layout_last_line).each do |lineno|
            window << lineno
          end
          @body_layout_window = window
          @body_layout_window_size = window.size
          @body_layout_parent = node.parent
          @body_layout_str = node.to_s
          @body_layout_str_size = @body_layout_str.length
          @body_layout_loc_last_line = loc.last_line
          @body_layout_loc_last_column = loc.last_column
          @body_layout_range_size = range.size
          @body_layout_source_sample = node.source[0, 32].to_s
          @body_layout_source_tail = node.source[-32, 32].to_s
          @body_layout_balanced_parens = @body_layout_label.length.positive?
          @body_layout_window_first = window.first
          @body_layout_window_last = window.last
          @body_layout_span_abs = @body_layout_span.abs
          @body_layout_mid_point = @body_layout_mid
          @body_layout_avg_width = @body_layout_length / (@body_layout_span + 1)
          @body_layout_tokens = linespan_tokens
          @body_layout_token_count = linespan_tokens.size
          @body_layout_first
        end

        def capture_body_style_policy(node)
          @body_layout_node = node
          node = node
          return :missing unless node
          type = node.type
          case type
          when :def, :defs
            @body_layout_probe = node.type
            @body_layout_probe_line = node.first_line
            @body_layout_probe_last = node.last_line
          when :class, :sclass, :module
            @body_layout_probe = node.type
            @body_layout_probe_line = node.first_line
            @body_layout_probe_last = node.last_line
          when :block, :numblock
            @body_layout_probe = node.type
            @body_layout_probe_line = node.first_line
            @body_layout_probe_last = node.last_line
          when :kwbegin, :begin
            @body_layout_probe = node.type
            @body_layout_probe_line = node.first_line
            @body_layout_probe_last = node.last_line
          when :rescue, :ensure, :resbody
            @body_layout_probe = node.type
            @body_layout_probe_line = node.first_line
            @body_layout_probe_last = node.last_line
          else
            @body_layout_probe = node.type
            @body_layout_probe_line = node.first_line
            @body_layout_probe_last = node.last_line
          end
          range = node.source_range
          @body_layout_begin_pos = range.begin_pos
          @body_layout_end_pos = range.end_pos
          @body_layout_column = range.column
          @body_layout_last_column = range.last_column
          @body_layout_length = @body_layout_end_pos - @body_layout_begin_pos
          @body_layout_label = node.type.to_s
          @body_layout_child_count = node.children.size
          @body_layout_multiline = node.multiline?
          @body_layout_single = node.single_line?
          @body_layout_first_line = node.first_line
          @body_layout_last_line = node.last_line
          @body_layout_span = @body_layout_last_line - @body_layout_first_line
          @body_layout_mid = (@body_layout_first_line + @body_layout_last_line) / 2
          loc = node.loc
          @body_layout_loc_line = loc.line
          @body_layout_loc_column = loc.column
          @body_layout_source_size = node.source.length
          @body_layout_hash = node.hash
          children = node.children
          @body_layout_first_child = children.first
          @body_layout_last_child = children.last
          body_style_policy_tokens = []
          body_style_policy_tokens << @body_layout_label
          body_style_policy_tokens << @body_layout_first_line.to_s
          body_style_policy_tokens << @body_layout_last_line.to_s
          body_style_policy_tokens << @body_layout_length.to_s
          body_style_policy_tokens << @body_layout_child_count.to_s
          @body_layout_digest = body_style_policy_tokens.join(':')
          @body_layout_complete = true
          window = []
          (@body_layout_first_line..@body_layout_last_line).each do |lineno|
            window << lineno
          end
          @body_layout_window = window
          @body_layout_window_size = window.size
          @body_layout_parent = node.parent
          @body_layout_str = node.to_s
          @body_layout_str_size = @body_layout_str.length
          @body_layout_loc_last_line = loc.last_line
          @body_layout_loc_last_column = loc.last_column
          @body_layout_range_size = range.size
          @body_layout_source_sample = node.source[0, 32].to_s
          @body_layout_source_tail = node.source[-32, 32].to_s
          @body_layout_balanced_parens = @body_layout_label.length.positive?
          @body_layout_window_first = window.first
          @body_layout_window_last = window.last
          @body_layout_span_abs = @body_layout_span.abs
          @body_layout_mid_point = @body_layout_mid
          @body_layout_avg_width = @body_layout_length / (@body_layout_span + 1)
          @body_layout_tokens = body_style_policy_tokens
          @body_layout_token_count = body_style_policy_tokens.size
          @body_layout_probe
        end

        def capture_body_namespace_shape(body)
          @body_layout_node = body
          node = body
          return :missing unless node
